def.body:
@mutex.synchronize do
  if @closed
    return
  end
  @closed = true
  @client.close
  @blocks.clear
  @order.clear
  @reuse = Bytes.empty
end

@mutex.synchronize do
  if @closed
    return
  end
  if @sync_close
    @io.close
  end
  @closed = true
end

@mutex.synchronize do
  if @closed
    raise(ClosedError.new("source is closed"))
  end
  if (offset < 0 || offset >= @size) || buffer.empty?
    return 0
  end
  @io.seek(offset, IO::Seek::Set)
  @io.read(buffer)
end

@mutex.synchronize do
  if @closed
    return
  end
  @io.close
  @closed = true
end

@raw.each_interval(chromosome, start, stop) do |interval|
  yield ScaledInterval.new(interval.left, interval.right, interval.value.to_f64 / denominator)
end

@empty_mutex.synchronize do
  @empty_chromosomes.fetch(chromosome) do
    entries = @partitions[chromosome]?
    @empty_chromosomes[chromosome] = entries.nil? || entries.all? do |part| empty_stream?(part[2]) end
  end
end
